def set_all_location_rules(world: PerfectDarkWorld) -> None:
    if world.options.weapon_progression.value == WeaponProgression.option_vanilla:
        if world.options.agent:
            # Stage 1 - Defection
            defection_agent_obj_1 = world.get_location("dD Defection - Agent Objective 1")
            add_rule(defection_agent_obj_1, lambda state: state.has_all(("dD Defection - Agent", "Falcon 2 (Silencer)", "CMP150"), world.player))

            defection_agent_complete = world.get_location("Complete: dD Defection - Agent")
            add_rule(defection_agent_complete, lambda state: state.has_all(("dD Defection - Agent", "Falcon 2 (Silencer)", "CMP150"), world.player))


            # Stage 2 - Investigation
            investigation_agent_obj_1 = world.get_location("dD Investigation - Agent Objective 1")
            add_rule(investigation_agent_obj_1, lambda state: state.has_all(("dD Investigation - Agent", "CamSpy", "Falcon 2"), world.player))

            investigation_agent_obj_2 = world.get_location("dD Investigation - Agent Objective 2")
            add_rule(investigation_agent_obj_2, lambda state: state.has_all(("dD Investigation - Agent", "CamSpy", "Falcon 2", "CMP150", "Data Uplink"), world.player))

            investigation_agent_complete = world.get_location("Complete: dD Investigation - Agent")
            add_rule(investigation_agent_complete, lambda state: state.has_all(("dD Investigation - Agent", "CamSpy", "Falcon 2", "CMP150", "Data Uplink"), world.player))
            

            # Stage 3 - Extraction
            extraction_agent_obj_1 = world.get_location("dD Extraction - Agent Objective 1")
            add_rule(extraction_agent_obj_1, lambda state: state.has_all(("dD Extraction - Agent", "Night Vision", "Falcon 2 (Scope)"), world.player))

            extraction_agent_obj_2 = world.get_location("dD Extraction - Agent Objective 2")
            add_rule(extraction_agent_obj_2, lambda state: state.has_all(("dD Extraction - Agent", "Night Vision", "Falcon 2 (Scope)", "CMP150", "Shotgun"), world.player))

            extraction_agent_obj_3 = world.get_location("dD Extraction - Agent Objective 3")
            add_rule(extraction_agent_obj_3, lambda state: state.has_all(("dD Extraction - Agent", "Night Vision", "Falcon 2 (Scope)", "CMP150", "Shotgun"), world.player))

            extraction_agent_complete = world.get_location("Complete: dD Extraction - Agent")
            add_rule(extraction_agent_complete, lambda state: state.has_all(("dD Extraction - Agent", "Night Vision", "Falcon 2 (Scope)", "CMP150", "Shotgun"), world.player))


            # Stage 4 - Villa
            villa_agent_obj_1 = world.get_location("Carrington Villa - Agent Objective 1")
            add_rule(villa_agent_obj_1, lambda state: state.has_all(("Carrington Villa - Agent", "Sniper Rifle"), world.player))

            villa_agent_obj_2 = world.get_location("Carrington Villa - Agent Objective 2")
            add_rule(villa_agent_obj_2, lambda state: state.has_all(("Carrington Villa - Agent", "Sniper Rifle", "CMP150"), world.player))

            villa_agent_obj_3 = world.get_location("Carrington Villa - Agent Objective 3")
            add_rule(villa_agent_obj_3, lambda state: state.has_all(("Carrington Villa - Agent", "Sniper Rifle", "CMP150", "Cellar Key Card"), world.player))

            villa_agent_complete = world.get_location("Complete: Carrington Villa - Agent")
            add_rule(villa_agent_complete, lambda state: state.has_all(("Carrington Villa - Agent", "Sniper Rifle", "CMP150", "Cellar Key Card"), world.player))


            # Stage 5 - Chicago
            if world.options.mission_logic.value == MissionLogic.option_normal:
                chicago_agent_obj_1 = world.get_location("Chicago - Agent Objective 1")
                add_rule(chicago_agent_obj_1, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)"), world.player))

                chicago_agent_obj_2 = world.get_location("Chicago - Agent Objective 2")
                add_rule(chicago_agent_obj_2, lambda state: state.has_all(("Chicago - Agent", "Data Uplink", "Falcon 2 (Scope)"), world.player))

                chicago_agent_obj_3 = world.get_location("Chicago - Agent Objective 3")
                add_rule(chicago_agent_obj_3, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)", "CMP150"), world.player))
                
                chicago_agent_complete = world.get_location("Complete: Chicago - Agent")
                add_rule(chicago_agent_complete, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)", "CMP150"), world.player))

            elif world.options.mission_logic.value == MissionLogic.option_veteran:
                chicago_agent_obj_1 = world.get_location("Chicago - Agent Objective 1")
                add_rule(chicago_agent_obj_1, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)"), world.player))

                chicago_agent_obj_2 = world.get_location("Chicago - Agent Objective 2")
                add_rule(chicago_agent_obj_2, lambda state: state.has_all(("Chicago - Agent", "Data Uplink", "Falcon 2 (Scope)"), world.player)
                                                            or state.has_all(("Chicago - Agent", "CamSpy", "Falcon 2 (Scope)"), world.player))

                chicago_agent_obj_3 = world.get_location("Chicago - Agent Objective 3")
                add_rule(chicago_agent_obj_3, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)", "CMP150"), world.player))
                
                chicago_agent_complete = world.get_location("Complete: Chicago - Agent")
                add_rule(chicago_agent_complete, lambda state: state.has_all(("Chicago - Agent", "Remote Mine", "Data Uplink", "Falcon 2 (Scope)", "CMP150"), world.player))


            # Stage 6 - G5 Building
            g5_agent_obj_1 = world.get_location("G5 Building - Agent Objective 1")
            add_rule(g5_agent_obj_1, lambda state: state.has_all(("G5 Building - Agent", "G5 Building Level 1 Key Card", "G5 Building Level 2 Key Card", "Falcon 2 (Silencer)", "CamSpy"), world.player)
                                                   or state.has_all(("G5 Building - Agent", "G5 Building Master Key", "Falcon 2 (Silencer)", "CamSpy"), world.player))

            g5_agent_obj_2 = world.get_location("G5 Building - Agent Objective 2")
            add_rule(g5_agent_obj_2, lambda state: state.has_all(("G5 Building - Agent", "G5 Building Level 1 Key Card", "G5 Building Level 2 Key Card", "Falcon 2 (Silencer)", "CMP150", "Door Decoder", "Backup Disk"), world.player)
                                                   or state.has_all(("G5 Building - Agent", "G5 Building Master Key", "Falcon 2 (Silencer)", "CMP150", "Door Decoder", "Backup Disk"), world.player))

            g5_agent_obj_3 = world.get_location("G5 Building - Agent Objective 3")
            add_rule(g5_agent_obj_3, lambda state: state.has_all(("G5 Building - Agent", "G5 Building Level 1 Key Card", "G5 Building Level 2 Key Card", "Falcon 2 (Silencer)", "CMP150", "Door Decoder", "Backup Disk"), world.player)
                                                   or state.has_all(("G5 Building - Agent", "G5 Building Master Key", "Falcon 2 (Silencer)", "CMP150", "Door Decoder", "Backup Disk"), world.player))

            g5_agent_complete = world.get_location("Complete: G5 Building - Agent")
            add_rule(g5_agent_complete, lambda state: state.has_all(("G5 Building - Agent", "G5 Building Level 1 Key Card", "G5 Building Level 2 Key Card", "Falcon 2 (Silencer)", "CMP150", "CamSpy", "Door Decoder", "Backup Disk"), world.player)
                                                      or state.has_all(("G5 Building - Agent", "G5 Building Master Key", "Falcon 2 (Silencer)", "CMP150", "CamSpy", "Door Decoder", "Backup Disk"), world.player))


            # Stage 7 - Infiltration
            infiltration_agent_obj_1 = world.get_location("A51 Infiltration - Agent Objective 1")
            add_rule(infiltration_agent_obj_1, lambda state: state.has_all(("A51 Infiltration - Agent", "Falcon 2", "Explosives"), world.player))

            infiltration_agent_obj_2 = world.get_location("A51 Infiltration - Agent Objective 2")
            add_rule(infiltration_agent_obj_2, lambda state: state.has_all(("A51 Infiltration - Agent", "Falcon 2", "Area 51 Lift Key Card"), world.player)
                                                             or state.has_all(("A51 Infiltration - Agent", "Falcon 2", "Area 51 Master Key"), world.player))

            infiltration_agent_obj_3 = world.get_location("A51 Infiltration - Agent Objective 3")
            add_rule(infiltration_agent_obj_3, lambda state: state.has_all(("A51 Infiltration - Agent", "Falcon 2", "MagSec 4", "Dragon", "Explosives", "Area 51 Lift Key Card"), world.player)
                                                             or state.has_all(("A51 Infiltration - Agent", "Falcon 2", "MagSec 4", "Dragon", "Explosives", "Area 51 Master Key"), world.player))

            infiltration_agent_complete = world.get_location("Complete: A51 Infiltration - Agent")
            add_rule(infiltration_agent_complete, lambda state: state.has_all(("A51 Infiltration - Agent", "Falcon 2", "MagSec 4", "Dragon", "Explosives", "Area 51 Lift Key Card"), world.player)
                                                                or state.has_all(("A51 Infiltration - Agent", "Falcon 2", "MagSec 4", "Dragon", "Explosives", "Area 51 Master Key"), world.player))


            # Stage 8 - Rescue
            rescue_agent_obj_1 = world.get_location("A51 Rescue - Agent Objective 1")
            add_rule(rescue_agent_obj_1, lambda state: state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "Lab Clothes"), world.player))

            rescue_agent_obj_2 = world.get_location("A51 Rescue - Agent Objective 2")
            add_rule(rescue_agent_obj_2, lambda state: state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "Lab Clothes", "Medlab 2 Key Card"), world.player)
                                                       or state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "Lab Clothes", "Area 51 Master Key"), world.player))

            rescue_agent_obj_3 = world.get_location("A51 Rescue - Agent Objective 3")
            add_rule(rescue_agent_obj_3, lambda state: state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "SuperDragon", "Lab Clothes", "Medlab 2 Key Card", "Op Room Key Card"), world.player)
                                                       or state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "SuperDragon", "Lab Clothes", "Area 51 Master Key"), world.player))
            
            rescue_agent_complete = world.get_location("Complete: A51 Rescue - Agent")
            add_rule(rescue_agent_complete, lambda state: state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "SuperDragon", "Lab Clothes", "Medlab 2 Key Card", "Op Room Key Card"), world.player)
                                                          or state.has_all(("A51 Rescue - Agent", "Falcon 2 (Silencer)", "Dragon", "SuperDragon", "Lab Clothes", "Area 51 Master Key"), world.player))


            # Stage 9 - Escape
            escape_agent_obj_1 = world.get_location("A51 Escape - Agent Objective 1")
            add_rule(escape_agent_obj_1, lambda state: state.has_all(("A51 Escape - Agent", "Falcon 2 (Scope)", "SuperDragon"), world.player))

            escape_agent_obj_2 = world.get_location("A51 Escape - Agent Objective 2")
            add_rule(escape_agent_obj_2, lambda state: state.has_all(("A51 Escape - Agent", "Falcon 2 (Scope)", "SuperDragon"), world.player))

            escape_agent_obj_3 = world.get_location("A51 Escape - Agent Objective 3")
            add_rule(escape_agent_obj_3, lambda state: state.has_all(("A51 Escape - Agent", "Falcon 2 (Scope)", "SuperDragon", "Alien Medpack"), world.player))
            
            escape_agent_complete = world.get_location("Complete: A51 Escape - Agent")
            add_rule(escape_agent_complete, lambda state: state.has_all(("A51 Escape - Agent", "Falcon 2 (Scope)", "SuperDragon", "Alien Medpack"), world.player))


            # Stage 10 - Air Base
            air_base_agent_obj_1 = world.get_location("Air Base - Agent Objective 1")
            add_rule(air_base_agent_obj_1, lambda state: state.has_all(("Air Base - Agent", "Crossbow", "Stewardess Disguise"), world.player)
                                                         or state.has_all(("Air Base - Agent", "CamSpy", "Stewardess Disguise"), world.player))

            air_base_agent_obj_2 = world.get_location("Air Base - Agent Objective 2")
            add_rule(air_base_agent_obj_2, lambda state: state.has_all(("Air Base - Agent", "Crossbow", "Stewardess Disguise"), world.player)
                                                         or state.has_all(("Air Base - Agent", "CamSpy", "Stewardess Disguise"), world.player))

            air_base_agent_obj_3 = world.get_location("Air Base - Agent Objective 3")
            add_rule(air_base_agent_obj_3, lambda state: state.has_all(("Air Base - Agent", "Crossbow", "Dragon", "K7 Avenger", "Stewardess Disguise"), world.player)
                                                         or state.has_all(("Air Base - Agent", "CamSpy", "Dragon", "K7 Avenger", "Stewardess Disguise"), world.player))
            
            air_base_agent_complete = world.get_location("Complete: Air Base - Agent")
            add_rule(air_base_agent_complete, lambda state: state.has_all(("Air Base - Agent", "Crossbow", "Dragon", "K7 Avenger", "Stewardess Disguise"), world.player)
                                                            or state.has_all(("Air Base - Agent", "CamSpy", "Dragon", "K7 Avenger", "Stewardess Disguise"), world.player))


            # Stage 11 - Air Force One
            if world.options.mission_logic.value == MissionLogic.option_normal:
                air_force_one_agent_obj_1 = world.get_location("Air Force One - Agent Objective 1")
                add_rule(air_force_one_agent_obj_1, lambda state: state.has_all(("Air Force One - Agent", "Suitcase"), world.player))

                air_force_one_agent_obj_2 = world.get_location("Air Force One - Agent Objective 2")
                add_rule(air_force_one_agent_obj_2, lambda state: state.has_all(("Air Force One - Agent", "Suitcase", "Laptop Gun", "K7 Avenger"), world.player))

                air_force_one_agent_obj_3 = world.get_location("Air Force One - Agent Objective 3")
                add_rule(air_force_one_agent_obj_3, lambda state: state.has_all(("Air Force One - Agent", "Suitcase", "Laptop Gun", "Timed Mine"), world.player))

                air_force_one_agent_complete = world.get_location("Complete: Air Force One - Agent")
                add_rule(air_force_one_agent_complete, lambda state: state.has_all(("Air Force One - Agent", "Suitcase", "Laptop Gun", "K7 Avenger", "Timed Mine"), world.player))

            elif world.options.mission_logic.value == MissionLogic.option_veteran:
                air_force_one_agent_obj_1 = world.get_location("Air Force One - Agent Objective 1")
                add_rule(air_force_one_agent_obj_1, lambda state: state.has_all(("Air Force One - Agent", "Suitcase"), world.player))

                air_force_one_agent_obj_2 = world.get_location("Air Force One - Agent Objective 2")
                add_rule(air_force_one_agent_obj_2, lambda state: state.has_all(("Air Force One - Agent", "Suitcase", "Laptop Gun", "K7 Avenger"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Suitcase", "Cyclone", "Air Force One Left Room Key Card", "K7 Avenger"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Suitcase", "Cyclone", "Air Force One Right Room Key Card", "K7 Avenger"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Suitcase", "Cyclone", "Air Force One Master Key", "K7 Avenger"), world.player))

                air_force_one_agent_obj_3 = world.get_location("Air Force One - Agent Objective 3")
                add_rule(air_force_one_agent_obj_3, lambda state: state.has_all(("Air Force One - Agent", "Laptop Gun", "Timed Mine"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Cyclone", "Air Force One Left Room Key Card", "Timed Mine"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Cyclone", "Air Force One Right Room Key Card", "Timed Mine"), world.player)
                                                                  or state.has_all(("Air Force One - Agent", "Cyclone", "Air Force One Master Key", "Timed Mine"), world.player))

                air_force_one_agent_complete = world.get_location("Complete: Air Force One - Agent")
